attachedTo.exampleCs:
foreach (var prop in Prop.All())
{
    if (prop.AttachedTo != null)
    {
        Log.Info($"{prop.MeshName} on {prop.AttachedTo.Nickname}'s {prop.Joint}");
    }
}

spawn.example:
const { Vector3 } = kcds.math;

const crate = kcds.world.Prop.spawn('crate_box_a', new Vector3(100, 200, 10), new Vector3(0, 0, 90), 1.5, 'static');
crate.physics = 'rigid';

// One of the game's houses, solid, with its windows and roof.
const house = kcds.world.Prop.spawn('prefab:house_1s_4r_angled_a_dobesovicko', new Vector3(120, 200, 10), new Vector3(0, 0, 90));
console.info(house.meshGroup);

spawn.exampleCs:
var crate = Prop.Spawn("crate_box_a", new Vector3(100, 200, 10), new Vector3(0, 0, 90), 1.5, "static");
crate.Physics = "rigid";

// One of the game's houses, solid, with its windows and roof.
var house = Prop.Spawn("prefab:house_1s_4r_angled_a_dobesovicko", new Vector3(120, 200, 10), new Vector3(0, 0, 90));
Log.Info(house.MeshGroup);

collisionOf.example:
// A pyre needs its own floor if the model collides only with simple shapes.
const { Prop } = kcds.world;
const { Vector3 } = kcds.math;

if (Prop.collisionOf('witch_stake') !== 'mesh') {
  const floor = Prop.spawn('objects/special/primitive_cube.cgf', new Vector3(812.4, 1530.2, 31.1), undefined, new Vector3(1, 1, 0.05));
  floor.visible = false;
}

collisionOf.exampleCs:
// A pyre needs its own floor if the model collides only with simple shapes.

if (Prop.CollisionOf("witch_stake").AsString() != "mesh")
{
    var floor = Prop.Spawn("objects/special/primitive_cube.cgf", new Vector3(812.4, 1530.2, 31.1), null, new Vector3(1, 1, 0.05));
    floor.Visible = false;
}

