setPose.example:
// An apple thrown at the pillory, along a short path.
const { Vector3 } = kcds.math;
let step = 0;

const flight = setInterval(() => {
  step += 1;
  apple.setPose(start.add(new Vector3(0, step * 0.5, 2 - step * step * 0.05)));
  if (step === 10) {
    clearInterval(flight);
  }
}, 50);

setPose.exampleCs:
// An apple thrown at the pillory, along a short path.
var step = 0;
JsValue flight = default;

flight = Timers.SetInterval(() =>
{
    step += 1;
    apple.SetPose(start.Add(new Vector3(0, step * 0.5, 2 - step * step * 0.05)));
    if (step == 10)
    {
        Timers.ClearInterval(flight);
    }
}, 50);

