resetPhysics.example:
for (const prop of kcds.world.Prop.all()) {
  if (prop.physics === 'rigid') {
    prop.resetPhysics();
  }
}

resetPhysics.exampleCs:
foreach (var prop in Prop.All())
{
    if (prop.Physics == "rigid")
    {
        prop.ResetPhysics();
    }
}
